import { CartIcon } from "../icons";

export function OrdersEmpty() {
  return (
    <div className="empty">
      <CartIcon aria-hidden />
      <h2>No orders yet</h2>
      <p>When you buy something, it shows up here.</p>
      <a href="/products">Browse products</a>
    </div>
  );
}
